const config = {
  "previewFeatures": [],
  "clientVersion": "7.4.2",
  "engineVersion": "94a226be1cf2967af2541cca5529f0f7ba866919",
  "activeProvider": "sqlite",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"./generated/client\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n}\n\n// === Models ===\n\nmodel User {\n  id           String    @id @default(cuid())\n  email        String    @unique\n  name         String\n  passwordHash String\n  role         String    @default(\"learner\")\n  tenantId     String?\n  tenant       Tenant?   @relation(fields: [tenantId], references: [id])\n  isActive     Boolean   @default(true)\n  lastLoginAt  DateTime?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  storeAssignments        UserStoreAssignment[]\n  regionAssignments       UserRegionAssignment[]\n  checklistSessions       ChecklistSession[]\n  createdSops             Sop[]\n  sopAcknowledgments      SopAcknowledgment[]\n  vmSubmissions           VmSubmission[]         @relation(\"VmSubmitter\")\n  vmReviews               VmSubmission[]         @relation(\"VmReviewer\")\n  standardEvaluations     StandardEvaluation[]\n  kpiEntries              KpiEntry[]             @relation(\"KpiEntries\")\n  budgetPeriods           BudgetPeriod[]         @relation(\"BudgetPeriods\")\n  forecasts               Forecast[]             @relation(\"Forecasts\")\n  lossReports             LossIncident[]         @relation(\"LossReporter\")\n  lossAssignments         LossIncident[]         @relation(\"LossAssignee\")\n  inventoryCounts         InventoryCount[]       @relation(\"InventoryConductor\")\n  floorPositions          FloorStaffPosition[]   @relation(\"FloorPositionUser\")\n  floorUpdates            FloorStaffPosition[]   @relation(\"FloorPositionUpdater\")\n  maintenanceReports      MaintenanceRequest[]   @relation(\"MaintenanceReporter\")\n  maintenanceAssignments  MaintenanceRequest[]   @relation(\"MaintenanceAssignee\")\n  courseCreations         Course[]               @relation(\"CourseCreator\")\n  courseEnrollments       CourseEnrollment[]     @relation(\"CourseEnrollments\")\n  certificates            Certificate[]          @relation(\"Certificates\")\n  trainingLogs            TrainingLog[]          @relation(\"TrainingLogs\")\n  challengeCreations      Challenge[]            @relation(\"ChallengeCreator\")\n  challengeParticipations ChallengeParticipant[] @relation(\"ChallengeParticipants\")\n  onboardingJourneys      OnboardingJourney[]    @relation(\"OnboardingJourneys\")\n  onboardingMentoring     OnboardingJourney[]    @relation(\"OnboardingMentors\")\n  coachSessions           CoachingSession[]      @relation(\"CoachSessions\")\n  coacheeSessions         CoachingSession[]      @relation(\"CoacheeSessions\")\n  devPlansAsUser          DevelopmentPlan[]      @relation(\"DevelopmentPlanUser\")\n  devPlansAsManager       DevelopmentPlan[]      @relation(\"DevelopmentPlanManager\")\n  devReviews              DevelopmentReview[]    @relation(\"DevelopmentReviewer\")\n  appraisalsAsEmployee    Appraisal[]            @relation(\"AppraisalEmployee\")\n  appraisalsAsManager     Appraisal[]            @relation(\"AppraisalManager\")\n  shiftEntries            ShiftEntry[]\n  swapRequests            ShiftSwapRequest[]     @relation(\"SwapRequester\")\n  wellbeingCheckIns       WellbeingCheckIn[]\n\n  @@index([tenantId])\n}\n\nmodel Tenant {\n  id           String   @id @default(cuid())\n  name         String\n  slug         String   @unique\n  status       String   @default(\"ACTIVE\")\n  contactEmail String?\n  contactName  String?\n  contactPhone String?\n  maxUsers     Int      @default(15)\n  logoUrl      String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  users               User[]\n  stores              Store[]\n  regions             Region[]\n  subscription        Subscription?\n  consents            DataProcessingConsent[]\n  checklistTemplates  ChecklistTemplate[]\n  checklistSessions   ChecklistSession[]\n  sopCategories       SopCategory[]\n  sops                Sop[]\n  vmGuidelines        VmGuideline[]\n  vmSubmissions       VmSubmission[]\n  standardCategories  StandardCategory[]\n  standardDefinitions StandardDefinition[]\n  standardEvaluations StandardEvaluation[]\n  kpiEntries          KpiEntry[]\n  budgetPeriods       BudgetPeriod[]\n  forecasts           Forecast[]\n  lossIncidents       LossIncident[]\n  inventoryCounts     InventoryCount[]\n  floorZones          FloorZone[]\n  floorPositions      FloorStaffPosition[]\n  footfallEntries     FootfallEntry[]\n  vmGuidelineDocs     VmGuidelineDoc[]\n  maintenanceRequests MaintenanceRequest[]\n  courses             Course[]\n  trainingLogs        TrainingLog[]\n  challenges          Challenge[]\n  onboardingTemplates OnboardingTemplate[]\n  onboardingJourneys  OnboardingJourney[]\n  coachingSessions    CoachingSession[]\n  developmentPlans    DevelopmentPlan[]\n  appraisalCycles     AppraisalCycle[]\n  pulseSurveys        PulseSurvey[]\n  wellbeingCheckIns   WellbeingCheckIn[]\n  wellbeingResources  WellbeingResource[]\n}\n\nmodel Region {\n  id          String   @id @default(cuid())\n  tenantId    String\n  tenant      Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  name        String\n  description String?\n  sortOrder   Int      @default(0)\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  stores          Store[]\n  userAssignments UserRegionAssignment[]\n\n  @@index([tenantId])\n}\n\nmodel Store {\n  id        String   @id @default(cuid())\n  tenantId  String\n  tenant    Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  regionId  String?\n  region    Region?  @relation(fields: [regionId], references: [id], onDelete: SetNull)\n  name      String\n  city      String?\n  address   String?\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tools                 StoreToolAssignment[]\n  userAssignments       UserStoreAssignment[]\n  auditSessions         AuditSession[]\n  checklistSessions     ChecklistSession[]\n  vmSubmissions         VmSubmission[]\n  standardEvaluations   StandardEvaluation[]\n  kpiEntries            KpiEntry[]\n  budgetPeriods         BudgetPeriod[]\n  forecasts             Forecast[]\n  lossIncidents         LossIncident[]\n  inventoryCounts       InventoryCount[]\n  floorZones            FloorZone[]\n  floorPositions        FloorStaffPosition[]\n  footfallEntries       FootfallEntry[]\n  maintenanceRequests   MaintenanceRequest[]\n  courseEnrollments     CourseEnrollment[]\n  trainingLogs          TrainingLog[]\n  challengeParticipants ChallengeParticipant[]\n  onboardingJourneys    OnboardingJourney[]\n  coachingSessions      CoachingSession[]\n  developmentPlans      DevelopmentPlan[]\n  appraisals            Appraisal[]\n  shiftTemplates        ShiftTemplate[]\n  shiftEntries          ShiftEntry[]\n  pulseResponses        PulseResponse[]\n  wellbeingCheckIns     WellbeingCheckIn[]\n\n  @@index([tenantId])\n  @@index([regionId])\n}\n\nmodel ToolDefinition {\n  id                String   @id @default(cuid())\n  key               String   @unique\n  name              String\n  description       String?\n  category          String\n  icon              String?\n  priceMonthly      Int      @default(0)\n  isActive          Boolean  @default(true)\n  sortOrder         Int      @default(0)\n  learnerAccessible Boolean  @default(false)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  assignments StoreToolAssignment[]\n\n  @@index([category])\n}\n\nmodel StoreToolAssignment {\n  id         String         @id @default(cuid())\n  storeId    String\n  store      Store          @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  toolId     String\n  tool       ToolDefinition @relation(fields: [toolId], references: [id], onDelete: Cascade)\n  isActive   Boolean        @default(true)\n  assignedAt DateTime       @default(now())\n  config     String?\n\n  @@unique([storeId, toolId])\n  @@index([storeId])\n  @@index([toolId])\n}\n\nmodel UserStoreAssignment {\n  id         String   @id @default(cuid())\n  userId     String\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  storeId    String\n  store      Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  assignedAt DateTime @default(now())\n\n  @@unique([userId, storeId])\n  @@index([userId])\n  @@index([storeId])\n}\n\nmodel Subscription {\n  id               String   @id @default(cuid())\n  tenantId         String   @unique\n  tenant           Tenant   @relation(fields: [tenantId], references: [id])\n  stripeCustomerId String   @unique\n  stripeSubId      String   @unique\n  status           String\n  currentPeriodEnd DateTime\n  cancelAtPeriod   Boolean  @default(false)\n}\n\n// GDPR: Audit-Log für Datenänderungen\nmodel AuditLog {\n  id        String   @id @default(cuid())\n  tenantId  String?\n  userId    String?\n  action    String\n  entity    String\n  entityId  String?\n  details   String?\n  ipAddress String?\n  createdAt DateTime @default(now())\n\n  @@index([tenantId])\n  @@index([createdAt])\n  @@index([entity, entityId])\n}\n\n// GDPR: Data Processing Agreement Tracking\nmodel DataProcessingConsent {\n  id          String    @id @default(cuid())\n  tenantId    String\n  tenant      Tenant    @relation(fields: [tenantId], references: [id])\n  consentType String\n  grantedAt   DateTime  @default(now())\n  grantedBy   String\n  revokedAt   DateTime?\n  revokedBy   String?\n  version     String\n  document    String?\n\n  @@unique([tenantId, consentType])\n  @@index([tenantId])\n}\n\nmodel UserRegionAssignment {\n  id         String   @id @default(cuid())\n  userId     String\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  regionId   String\n  region     Region   @relation(fields: [regionId], references: [id], onDelete: Cascade)\n  assignedAt DateTime @default(now())\n\n  @@unique([userId, regionId])\n  @@index([userId])\n  @@index([regionId])\n}\n\n// ============================================================\n// Store Excellence Audit — Tool Models\n// Verknüpft mit Store (FK), aber unabhängig von anderen Tool-Models\n// ============================================================\n\nmodel AuditTemplate {\n  id          String   @id @default(cuid())\n  tenantId    String? // null = KORE-Default, non-null = Tenant-spezifisch\n  name        String\n  description String?\n  version     Int      @default(1)\n  isDefault   Boolean  @default(false)\n  isActive    Boolean  @default(true)\n  createdBy   String\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  categories AuditCategory[]\n  sessions   AuditSession[]\n\n  @@index([tenantId])\n}\n\nmodel AuditCategory {\n  id          String        @id @default(cuid())\n  templateId  String\n  template    AuditTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  name        String\n  description String?\n  sortOrder   Int           @default(0)\n  weight      Float         @default(1.0)\n\n  criteria AuditCriterion[]\n\n  @@index([templateId])\n}\n\nmodel AuditCriterion {\n  id            String        @id @default(cuid())\n  categoryId    String\n  category      AuditCategory @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n  name          String\n  description   String?\n  sortOrder     Int           @default(0)\n  isRequired    Boolean       @default(true)\n  photoRequired Boolean       @default(false)\n\n  responses AuditResponse[]\n\n  @@index([categoryId])\n}\n\nmodel AuditSession {\n  id            String        @id @default(cuid())\n  tenantId      String\n  storeId       String\n  store         Store         @relation(fields: [storeId], references: [id])\n  templateId    String\n  template      AuditTemplate @relation(fields: [templateId], references: [id])\n  conductedBy   String\n  storeLocation String? // Optionaler Sub-Bereich im Store\n  status        String        @default(\"DRAFT\") // DRAFT, IN_PROGRESS, COMPLETED, CANCELLED\n  overallScore  Float?\n  notes         String?\n  startedAt     DateTime?\n  completedAt   DateTime?\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  responses AuditResponse[]\n\n  @@index([tenantId])\n  @@index([storeId])\n  @@index([tenantId, completedAt])\n  @@index([conductedBy])\n}\n\nmodel AuditResponse {\n  id           String         @id @default(cuid())\n  sessionId    String\n  session      AuditSession   @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  criterionId  String\n  criterion    AuditCriterion @relation(fields: [criterionId], references: [id])\n  scorePercent Int?\n  passed       Boolean?\n  comment      String?\n  photoPath    String?\n  createdAt    DateTime       @default(now())\n  updatedAt    DateTime       @updatedAt\n\n  @@unique([sessionId, criterionId])\n  @@index([sessionId])\n}\n\n// ============================================================\n// Checklisten Tool — Einfache Checklisten für Store-Visits\n// ============================================================\n\nmodel ChecklistTemplate {\n  id          String   @id @default(cuid())\n  tenantId    String?\n  tenant      Tenant?  @relation(fields: [tenantId], references: [id])\n  name        String\n  description String?\n  version     Int      @default(1)\n  isDefault   Boolean  @default(false)\n  isActive    Boolean  @default(true)\n  createdBy   String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  sections ChecklistSection[]\n  sessions ChecklistSession[]\n\n  @@index([tenantId])\n}\n\nmodel ChecklistSection {\n  id         String            @id @default(cuid())\n  templateId String\n  template   ChecklistTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  name       String\n  sortOrder  Int               @default(0)\n\n  items ChecklistItem[]\n\n  @@index([templateId])\n}\n\nmodel ChecklistItem {\n  id         String           @id @default(cuid())\n  sectionId  String\n  section    ChecklistSection @relation(fields: [sectionId], references: [id], onDelete: Cascade)\n  text       String\n  type       String           @default(\"BOOLEAN\") // BOOLEAN, TEXT, NUMBER, PHOTO\n  isRequired Boolean          @default(false)\n  sortOrder  Int              @default(0)\n\n  entries ChecklistEntry[]\n\n  @@index([sectionId])\n}\n\nmodel ChecklistSession {\n  id             String            @id @default(cuid())\n  tenantId       String\n  tenant         Tenant            @relation(fields: [tenantId], references: [id])\n  storeId        String\n  store          Store             @relation(fields: [storeId], references: [id])\n  templateId     String\n  template       ChecklistTemplate @relation(fields: [templateId], references: [id])\n  conductedBy    String\n  conductor      User              @relation(fields: [conductedBy], references: [id])\n  status         String            @default(\"IN_PROGRESS\") // IN_PROGRESS, COMPLETED, CANCELLED\n  completionRate Float             @default(0)\n  notes          String?\n  startedAt      DateTime          @default(now())\n  completedAt    DateTime?\n\n  entries ChecklistEntry[]\n\n  @@index([tenantId])\n  @@index([storeId])\n  @@index([conductedBy])\n}\n\nmodel ChecklistEntry {\n  id          String           @id @default(cuid())\n  sessionId   String\n  session     ChecklistSession @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  itemId      String\n  item        ChecklistItem    @relation(fields: [itemId], references: [id])\n  valueBool   Boolean?\n  valueText   String?\n  valueNumber Float?\n  photoPath   String?\n  comment     String?\n  answeredAt  DateTime         @default(now())\n\n  @@unique([sessionId, itemId])\n  @@index([sessionId])\n}\n\n// ============================================================\n// SOP Bibliothek — Standard Operating Procedures\n// ============================================================\n\nmodel SopCategory {\n  id        String  @id @default(cuid())\n  tenantId  String?\n  tenant    Tenant? @relation(fields: [tenantId], references: [id])\n  name      String\n  sortOrder Int     @default(0)\n  isActive  Boolean @default(true)\n\n  documents Sop[]\n\n  @@index([tenantId])\n}\n\nmodel Sop {\n  id             String      @id @default(cuid())\n  tenantId       String?\n  tenant         Tenant?     @relation(fields: [tenantId], references: [id])\n  categoryId     String\n  category       SopCategory @relation(fields: [categoryId], references: [id])\n  title          String\n  content        String // Markdown\n  version        Int         @default(1)\n  status         String      @default(\"DRAFT\") // DRAFT, PUBLISHED, ARCHIVED\n  createdBy      String\n  creator        User        @relation(fields: [createdBy], references: [id])\n  attachmentPath String?\n  publishedAt    DateTime?\n  createdAt      DateTime    @default(now())\n  updatedAt      DateTime    @updatedAt\n\n  acknowledgments SopAcknowledgment[]\n\n  @@index([tenantId])\n  @@index([categoryId])\n}\n\nmodel SopAcknowledgment {\n  id             String   @id @default(cuid())\n  sopId          String\n  sop            Sop      @relation(fields: [sopId], references: [id], onDelete: Cascade)\n  userId         String\n  user           User     @relation(fields: [userId], references: [id])\n  acknowledgedAt DateTime @default(now())\n\n  @@unique([sopId, userId])\n  @@index([sopId])\n}\n\n// ============================================================\n// VM Foto-Compliance — Foto-basierte VM-Compliance-Checks\n// ============================================================\n\nmodel VmGuideline {\n  id             String   @id @default(cuid())\n  tenantId       String\n  tenant         Tenant   @relation(fields: [tenantId], references: [id])\n  name           String\n  description    String?\n  category       String? // z.B. \"Schaufenster\", \"Eingang\", \"Kasse\"\n  referencePhoto String? // Pfad zum Referenzbild\n  isActive       Boolean  @default(true)\n  sortOrder      Int      @default(0)\n  createdBy      String\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  submissions VmSubmission[]\n\n  @@index([tenantId])\n}\n\nmodel VmSubmission {\n  id          String      @id @default(cuid())\n  tenantId    String\n  tenant      Tenant      @relation(fields: [tenantId], references: [id])\n  guidelineId String\n  guideline   VmGuideline @relation(fields: [guidelineId], references: [id])\n  storeId     String\n  store       Store       @relation(fields: [storeId], references: [id])\n  submittedBy String\n  submitter   User        @relation(\"VmSubmitter\", fields: [submittedBy], references: [id])\n  photoPath   String\n  status      String      @default(\"PENDING\") // PENDING, APPROVED, REJECTED\n  reviewedBy  String?\n  reviewer    User?       @relation(\"VmReviewer\", fields: [reviewedBy], references: [id])\n  reviewNote  String?\n  submittedAt DateTime    @default(now())\n  reviewedAt  DateTime?\n\n  @@index([tenantId])\n  @@index([storeId])\n  @@index([guidelineId])\n  @@index([status])\n}\n\n// ============================================================\n// Store Standards — Store-Standards definieren, messen, benchmarken\n// ============================================================\n\nmodel StandardCategory {\n  id          String  @id @default(cuid())\n  tenantId    String?\n  tenant      Tenant? @relation(fields: [tenantId], references: [id])\n  name        String\n  description String?\n  sortOrder   Int     @default(0)\n  isActive    Boolean @default(true)\n\n  definitions StandardDefinition[]\n\n  @@index([tenantId])\n}\n\nmodel StandardDefinition {\n  id          String           @id @default(cuid())\n  categoryId  String\n  category    StandardCategory @relation(fields: [categoryId], references: [id])\n  tenantId    String?\n  tenant      Tenant?          @relation(fields: [tenantId], references: [id])\n  name        String\n  description String?\n  unit        String? // z.B. \"%\", \"min\", \"€\", \"Anzahl\"\n  targetValue Float\n  operator    String           @default(\"GTE\") // GTE, LTE, EQ, GT, LT\n  weight      Float            @default(1)\n  isActive    Boolean          @default(true)\n  sortOrder   Int              @default(0)\n\n  scores StandardScore[]\n\n  @@index([categoryId])\n  @@index([tenantId])\n}\n\nmodel StandardEvaluation {\n  id           String    @id @default(cuid())\n  tenantId     String\n  tenant       Tenant    @relation(fields: [tenantId], references: [id])\n  storeId      String\n  store        Store     @relation(fields: [storeId], references: [id])\n  evaluatedBy  String\n  evaluator    User      @relation(fields: [evaluatedBy], references: [id])\n  period       String // z.B. \"2025-KW12\" oder \"2025-03\"\n  overallScore Float?\n  notes        String?\n  status       String    @default(\"IN_PROGRESS\") // IN_PROGRESS, COMPLETED\n  evaluatedAt  DateTime  @default(now())\n  completedAt  DateTime?\n\n  scores StandardScore[]\n\n  @@index([tenantId])\n  @@index([storeId])\n  @@index([evaluatedBy])\n}\n\nmodel StandardScore {\n  id           String             @id @default(cuid())\n  evaluationId String\n  evaluation   StandardEvaluation @relation(fields: [evaluationId], references: [id], onDelete: Cascade)\n  definitionId String\n  definition   StandardDefinition @relation(fields: [definitionId], references: [id])\n  actualValue  Float\n  passed       Boolean\n  score        Float // 0-100\n  comment      String?\n\n  @@unique([evaluationId, definitionId])\n  @@index([evaluationId])\n}\n\n// ============================================================\n// KPI Dashboard (Pulse) — Tägliche Store-KPIs\n// ============================================================\n\nmodel KpiEntry {\n  id           String   @id @default(cuid())\n  tenantId     String\n  tenant       Tenant   @relation(fields: [tenantId], references: [id])\n  storeId      String\n  store        Store    @relation(fields: [storeId], references: [id])\n  date         String // ISO date \"2025-03-12\"\n  revenue      Float    @default(0)\n  transactions Int      @default(0)\n  footfall     Int?\n  unitsSold    Int?\n  staffHours   Float?\n  enteredBy    String\n  user         User     @relation(\"KpiEntries\", fields: [enteredBy], references: [id])\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  @@unique([storeId, date])\n  @@index([tenantId])\n  @@index([storeId])\n  @@index([date])\n}\n\n// ============================================================\n// Budget Tracker — Budget-Planung und Kostenverfolgung\n// ============================================================\n\nmodel BudgetPeriod {\n  id         String   @id @default(cuid())\n  tenantId   String\n  tenant     Tenant   @relation(fields: [tenantId], references: [id])\n  storeId    String\n  store      Store    @relation(fields: [storeId], references: [id])\n  period     String // z.B. \"2025-03\" oder \"2025-Q1\"\n  budgetType String   @default(\"MONTHLY\") // MONTHLY, QUARTERLY, YEARLY\n  revenue    Float    @default(0) // Budget-Ziel Umsatz\n  cogs       Float    @default(0) // Cost of Goods Sold\n  labor      Float    @default(0) // Personalkosten\n  rent       Float    @default(0) // Miete\n  marketing  Float    @default(0) // Marketing-Budget\n  other      Float    @default(0) // Sonstige Kosten\n  notes      String?\n  createdBy  String\n  user       User     @relation(\"BudgetPeriods\", fields: [createdBy], references: [id])\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  actuals BudgetActual[]\n\n  @@unique([storeId, period, budgetType])\n  @@index([tenantId])\n  @@index([storeId])\n}\n\nmodel BudgetActual {\n  id             String       @id @default(cuid())\n  budgetPeriodId String\n  budgetPeriod   BudgetPeriod @relation(fields: [budgetPeriodId], references: [id], onDelete: Cascade)\n  category       String // REVENUE, COGS, LABOR, RENT, MARKETING, OTHER\n  actualAmount   Float\n  date           String // ISO date\n  description    String?\n  enteredBy      String\n  createdAt      DateTime     @default(now())\n\n  @@index([budgetPeriodId])\n}\n\n// ============================================================\n// Forecast — Umsatz- und Performance-Prognosen\n// ============================================================\n\nmodel Forecast {\n  id            String   @id @default(cuid())\n  tenantId      String\n  tenant        Tenant   @relation(fields: [tenantId], references: [id])\n  storeId       String\n  store         Store    @relation(fields: [storeId], references: [id])\n  period        String // z.B. \"2025-03\" oder \"2025-KW12\"\n  forecastType  String   @default(\"REVENUE\") // REVENUE, TRANSACTIONS, FOOTFALL\n  forecastValue Float\n  actualValue   Float?\n  confidence    Float? // 0-100\n  method        String   @default(\"MANUAL\") // MANUAL, TREND, AI\n  notes         String?\n  createdBy     String\n  user          User     @relation(\"Forecasts\", fields: [createdBy], references: [id])\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@unique([storeId, period, forecastType])\n  @@index([tenantId])\n  @@index([storeId])\n}\n\n// ============================================================\n// Loss Prevention — Schwund-Erkennung und Verlustprävention\n// ============================================================\n\nmodel LossIncident {\n  id           String    @id @default(cuid())\n  tenantId     String\n  tenant       Tenant    @relation(fields: [tenantId], references: [id])\n  storeId      String\n  store        Store     @relation(fields: [storeId], references: [id])\n  incidentDate String // ISO date\n  category     String // THEFT, DAMAGE, ADMIN_ERROR, SUPPLIER, OTHER\n  amount       Float // Wert in EUR/Cent\n  description  String\n  severity     String    @default(\"MEDIUM\") // LOW, MEDIUM, HIGH, CRITICAL\n  status       String    @default(\"OPEN\") // OPEN, INVESTIGATING, RESOLVED, CLOSED\n  resolution   String?\n  reportedBy   String\n  reporter     User      @relation(\"LossReporter\", fields: [reportedBy], references: [id])\n  assignedTo   String?\n  assignee     User?     @relation(\"LossAssignee\", fields: [assignedTo], references: [id])\n  photoPath    String?\n  resolvedAt   DateTime?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@index([tenantId])\n  @@index([storeId])\n  @@index([status])\n  @@index([incidentDate])\n}\n\n// ============================================================\n// Inventory — Bestandsmanagement und Inventur\n// ============================================================\n\nmodel InventoryCount {\n  id            String    @id @default(cuid())\n  tenantId      String\n  tenant        Tenant    @relation(fields: [tenantId], references: [id])\n  storeId       String\n  store         Store     @relation(fields: [storeId], references: [id])\n  countDate     String // ISO date\n  countType     String    @default(\"FULL\") // FULL, PARTIAL, CYCLE\n  status        String    @default(\"IN_PROGRESS\") // IN_PROGRESS, COMPLETED, CANCELLED\n  totalItems    Int       @default(0)\n  countedItems  Int       @default(0)\n  discrepancies Int       @default(0)\n  totalValue    Float     @default(0)\n  notes         String?\n  conductedBy   String\n  conductor     User      @relation(\"InventoryConductor\", fields: [conductedBy], references: [id])\n  completedAt   DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  items InventoryItem[]\n\n  @@index([tenantId])\n  @@index([storeId])\n  @@index([countDate])\n}\n\nmodel InventoryItem {\n  id               String         @id @default(cuid())\n  countId          String\n  count            InventoryCount @relation(fields: [countId], references: [id], onDelete: Cascade)\n  sku              String\n  productName      String\n  category         String?\n  expectedQty      Int            @default(0)\n  actualQty        Int            @default(0)\n  unitPrice        Float          @default(0)\n  discrepancy      Int            @default(0) // actualQty - expectedQty\n  discrepancyValue Float          @default(0)\n  notes            String?\n  countedAt        DateTime?\n\n  @@unique([countId, sku])\n  @@index([countId])\n}\n\n// ============================================================\n// Floor in Echtzeit — Live Floor, FR Tracking, VM Guidelines, Maintenance\n// ============================================================\n\nmodel FloorZone {\n  id          String   @id @default(cuid())\n  tenantId    String\n  tenant      Tenant   @relation(fields: [tenantId], references: [id])\n  storeId     String\n  store       Store    @relation(fields: [storeId], references: [id])\n  name        String\n  description String?\n  sortOrder   Int      @default(0)\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  positions FloorStaffPosition[]\n\n  @@index([tenantId])\n  @@index([storeId])\n}\n\nmodel FloorStaffPosition {\n  id        String     @id @default(cuid())\n  tenantId  String\n  tenant    Tenant     @relation(fields: [tenantId], references: [id])\n  storeId   String\n  store     Store      @relation(fields: [storeId], references: [id])\n  zoneId    String?\n  zone      FloorZone? @relation(fields: [zoneId], references: [id])\n  userId    String\n  user      User       @relation(\"FloorPositionUser\", fields: [userId], references: [id])\n  userName  String // denormalized for quick display\n  role      String? // staff role on floor\n  status    String     @default(\"ON_FLOOR\") // ON_FLOOR, ON_BREAK, OFF_FLOOR, CASHIER\n  startedAt DateTime   @default(now())\n  endedAt   DateTime?\n  notes     String?\n  updatedBy String\n  updater   User       @relation(\"FloorPositionUpdater\", fields: [updatedBy], references: [id])\n  createdAt DateTime   @default(now())\n  updatedAt DateTime   @updatedAt\n\n  @@index([tenantId, storeId])\n  @@index([storeId, status])\n}\n\nmodel FootfallEntry {\n  id             String   @id @default(cuid())\n  tenantId       String\n  tenant         Tenant   @relation(fields: [tenantId], references: [id])\n  storeId        String\n  store          Store    @relation(fields: [storeId], references: [id])\n  date           String // ISO date \"2025-03-12\"\n  hour           Int? // 0-23, null = daily aggregate\n  footfall       Int      @default(0)\n  revenue        Float    @default(0)\n  transactions   Int      @default(0)\n  conversionRate Float?\n  enteredBy      String\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  @@unique([storeId, date, hour])\n  @@index([tenantId])\n  @@index([storeId])\n  @@index([date])\n}\n\nmodel VmGuidelineDoc {\n  id            String    @id @default(cuid())\n  tenantId      String\n  tenant        Tenant    @relation(fields: [tenantId], references: [id])\n  title         String\n  category      String? // z.B. \"Schaufenster\", \"Eingang\", \"Warenträger\"\n  content       String // Markdown\n  version       Int       @default(1)\n  status        String    @default(\"DRAFT\") // DRAFT, PUBLISHED, ARCHIVED\n  effectiveFrom String? // ISO date\n  effectiveTo   String? // ISO date\n  createdBy     String\n  publishedAt   DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  images VmGuidelineImage[]\n\n  @@index([tenantId])\n  @@index([status])\n}\n\nmodel VmGuidelineImage {\n  id             String         @id @default(cuid())\n  guidelineDocId String\n  guidelineDoc   VmGuidelineDoc @relation(fields: [guidelineDocId], references: [id], onDelete: Cascade)\n  imagePath      String\n  caption        String?\n  sortOrder      Int            @default(0)\n  createdAt      DateTime       @default(now())\n\n  @@index([guidelineDocId])\n}\n\nmodel MaintenanceRequest {\n  id            String    @id @default(cuid())\n  tenantId      String\n  tenant        Tenant    @relation(fields: [tenantId], references: [id])\n  storeId       String\n  store         Store     @relation(fields: [storeId], references: [id])\n  title         String\n  description   String\n  category      String    @default(\"OTHER\") // ELECTRICAL, PLUMBING, HVAC, FIXTURE, IT, OTHER\n  priority      String    @default(\"MEDIUM\") // LOW, MEDIUM, HIGH, URGENT\n  status        String    @default(\"OPEN\") // OPEN, IN_PROGRESS, WAITING_PARTS, RESOLVED, CLOSED\n  reportedBy    String\n  reporter      User      @relation(\"MaintenanceReporter\", fields: [reportedBy], references: [id])\n  assignedTo    String?\n  assignee      User?     @relation(\"MaintenanceAssignee\", fields: [assignedTo], references: [id])\n  estimatedCost Float?\n  actualCost    Float?\n  photoPath     String?\n  resolvedAt    DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  @@index([tenantId])\n  @@index([storeId])\n  @@index([status])\n  @@index([priority])\n}\n\n// ============================================================\n// Training Hub / LMS\n// ============================================================\n\nmodel Course {\n  id              String   @id @default(cuid())\n  tenantId        String\n  tenant          Tenant   @relation(fields: [tenantId], references: [id])\n  title           String\n  description     String?\n  category        String?\n  durationMinutes Int      @default(0)\n  isRequired      Boolean  @default(false)\n  status          String   @default(\"DRAFT\") // DRAFT, PUBLISHED, ARCHIVED\n  createdBy       String\n  creator         User     @relation(\"CourseCreator\", fields: [createdBy], references: [id])\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  modules     CourseModule[]\n  enrollments CourseEnrollment[]\n\n  @@index([tenantId])\n  @@index([status])\n}\n\nmodel CourseModule {\n  id              String   @id @default(cuid())\n  courseId        String\n  course          Course   @relation(fields: [courseId], references: [id], onDelete: Cascade)\n  title           String\n  content         String? // Markdown\n  sortOrder       Int      @default(0)\n  durationMinutes Int      @default(0)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  @@index([courseId])\n}\n\nmodel CourseEnrollment {\n  id            String    @id @default(cuid())\n  courseId      String\n  course        Course    @relation(fields: [courseId], references: [id])\n  userId        String\n  user          User      @relation(\"CourseEnrollments\", fields: [userId], references: [id])\n  storeId       String\n  store         Store     @relation(fields: [storeId], references: [id])\n  status        String    @default(\"ENROLLED\") // ENROLLED, IN_PROGRESS, COMPLETED\n  progress      Int       @default(0) // 0-100\n  completedAt   DateTime?\n  certificateId String?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  certificate Certificate?\n\n  @@unique([courseId, userId])\n  @@index([userId])\n  @@index([storeId])\n}\n\nmodel Certificate {\n  id           String           @id @default(cuid())\n  enrollmentId String           @unique\n  enrollment   CourseEnrollment @relation(fields: [enrollmentId], references: [id])\n  userId       String\n  user         User             @relation(\"Certificates\", fields: [userId], references: [id])\n  courseName   String\n  issuedAt     DateTime         @default(now())\n  expiresAt    DateTime?\n\n  @@index([userId])\n}\n\n// ============================================================\n// Training Hours\n// ============================================================\n\nmodel TrainingLog {\n  id              String   @id @default(cuid())\n  tenantId        String\n  tenant          Tenant   @relation(fields: [tenantId], references: [id])\n  storeId         String\n  store           Store    @relation(fields: [storeId], references: [id])\n  userId          String\n  user            User     @relation(\"TrainingLogs\", fields: [userId], references: [id])\n  date            String // ISO date\n  durationMinutes Int\n  category        String   @default(\"OTHER\") // PRODUCT, SALES, SERVICE, COMPLIANCE, ONBOARDING, OTHER\n  topic           String?\n  notes           String?\n  verifiedBy      String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  @@index([tenantId])\n  @@index([storeId])\n  @@index([userId])\n  @@index([date])\n}\n\n// ============================================================\n// Challenges\n// ============================================================\n\nmodel Challenge {\n  id          String   @id @default(cuid())\n  tenantId    String\n  tenant      Tenant   @relation(fields: [tenantId], references: [id])\n  title       String\n  description String?\n  type        String   @default(\"INDIVIDUAL\") // INDIVIDUAL, TEAM, STORE\n  metric      String?\n  targetValue Float?\n  startDate   String\n  endDate     String\n  reward      String?\n  status      String   @default(\"DRAFT\") // DRAFT, ACTIVE, COMPLETED, CANCELLED\n  createdBy   String\n  creator     User     @relation(\"ChallengeCreator\", fields: [createdBy], references: [id])\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  participants ChallengeParticipant[]\n\n  @@index([tenantId])\n  @@index([status])\n}\n\nmodel ChallengeParticipant {\n  id           String    @id @default(cuid())\n  challengeId  String\n  challenge    Challenge @relation(fields: [challengeId], references: [id], onDelete: Cascade)\n  userId       String\n  user         User      @relation(\"ChallengeParticipants\", fields: [userId], references: [id])\n  storeId      String?\n  store        Store?    @relation(fields: [storeId], references: [id])\n  currentValue Float     @default(0)\n  rank         Int?\n  completedAt  DateTime?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@unique([challengeId, userId])\n  @@index([userId])\n}\n\n// ============================================================\n// Onboarding\n// ============================================================\n\nmodel OnboardingTemplate {\n  id           String   @id @default(cuid())\n  tenantId     String\n  tenant       Tenant   @relation(fields: [tenantId], references: [id])\n  name         String\n  role         String? // Target role for this template\n  durationDays Int      @default(30)\n  isDefault    Boolean  @default(false)\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  steps    OnboardingStep[]\n  journeys OnboardingJourney[]\n\n  @@index([tenantId])\n}\n\nmodel OnboardingStep {\n  id          String             @id @default(cuid())\n  templateId  String\n  template    OnboardingTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  title       String\n  description String?\n  category    String?\n  dayNumber   Int                @default(1)\n  sortOrder   Int                @default(0)\n  isRequired  Boolean            @default(true)\n  createdAt   DateTime           @default(now())\n\n  progress OnboardingProgress[]\n\n  @@index([templateId])\n}\n\nmodel OnboardingJourney {\n  id          String             @id @default(cuid())\n  templateId  String\n  template    OnboardingTemplate @relation(fields: [templateId], references: [id])\n  tenantId    String\n  tenant      Tenant             @relation(fields: [tenantId], references: [id])\n  storeId     String\n  store       Store              @relation(fields: [storeId], references: [id])\n  userId      String\n  user        User               @relation(\"OnboardingJourneys\", fields: [userId], references: [id])\n  mentorId    String?\n  mentor      User?              @relation(\"OnboardingMentors\", fields: [mentorId], references: [id])\n  startDate   String\n  status      String             @default(\"IN_PROGRESS\") // IN_PROGRESS, COMPLETED, CANCELLED\n  completedAt DateTime?\n  createdAt   DateTime           @default(now())\n  updatedAt   DateTime           @updatedAt\n\n  progress OnboardingProgress[]\n\n  @@index([tenantId])\n  @@index([storeId])\n  @@index([userId])\n}\n\nmodel OnboardingProgress {\n  id          String            @id @default(cuid())\n  journeyId   String\n  journey     OnboardingJourney @relation(fields: [journeyId], references: [id], onDelete: Cascade)\n  stepId      String\n  step        OnboardingStep    @relation(fields: [stepId], references: [id])\n  status      String            @default(\"PENDING\") // PENDING, IN_PROGRESS, COMPLETED, SKIPPED\n  completedAt DateTime?\n  notes       String?\n  verifiedBy  String?\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n\n  @@unique([journeyId, stepId])\n  @@index([journeyId])\n}\n\n// ============================================================\n// Coaching & Development\n// ============================================================\n\nmodel CoachingSession {\n  id           String    @id @default(cuid())\n  tenantId     String\n  storeId      String\n  coachId      String\n  coacheeId    String\n  scheduledAt  DateTime\n  duration     Int       @default(30)\n  type         String    @default(\"REGULAR\") // REGULAR, AD_HOC, FOLLOW_UP\n  status       String    @default(\"SCHEDULED\") // SCHEDULED, COMPLETED, CANCELLED\n  notes        String?\n  actionItems  String?\n  mood         Int? // 1-5\n  followUpDate DateTime?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  tenant  Tenant @relation(fields: [tenantId], references: [id])\n  store   Store  @relation(fields: [storeId], references: [id])\n  coach   User   @relation(\"CoachSessions\", fields: [coachId], references: [id])\n  coachee User   @relation(\"CoacheeSessions\", fields: [coacheeId], references: [id])\n}\n\nmodel DevelopmentPlan {\n  id         String    @id @default(cuid())\n  tenantId   String\n  storeId    String?\n  userId     String\n  managerId  String\n  type       String // PDP, PIP\n  title      String\n  status     String    @default(\"ACTIVE\") // ACTIVE, COMPLETED, CANCELLED\n  startDate  DateTime  @default(now())\n  targetDate DateTime?\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n\n  tenant  Tenant              @relation(fields: [tenantId], references: [id])\n  store   Store?              @relation(fields: [storeId], references: [id])\n  user    User                @relation(\"DevelopmentPlanUser\", fields: [userId], references: [id])\n  manager User                @relation(\"DevelopmentPlanManager\", fields: [managerId], references: [id])\n  goals   DevelopmentGoal[]\n  reviews DevelopmentReview[]\n}\n\nmodel DevelopmentGoal {\n  id               String    @id @default(cuid())\n  planId           String\n  title            String\n  measureOfSuccess String?\n  targetDate       DateTime?\n  status           String    @default(\"NOT_STARTED\") // NOT_STARTED, IN_PROGRESS, COMPLETED\n  progress         Int       @default(0)\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n\n  plan DevelopmentPlan @relation(fields: [planId], references: [id])\n}\n\nmodel DevelopmentReview {\n  id              String   @id @default(cuid())\n  planId          String\n  reviewedBy      String\n  reviewDate      DateTime @default(now())\n  overallProgress Int      @default(0)\n  comments        String?\n  createdAt       DateTime @default(now())\n\n  plan     DevelopmentPlan @relation(fields: [planId], references: [id])\n  reviewer User            @relation(\"DevelopmentReviewer\", fields: [reviewedBy], references: [id])\n}\n\n// ============================================================\n// Appraisals / Performance Reviews\n// ============================================================\n\nmodel AppraisalCycle {\n  id        String   @id @default(cuid())\n  tenantId  String\n  name      String\n  period    String? // e.g. \"Q1 2025\", \"H1 2025\"\n  startDate DateTime\n  endDate   DateTime\n  status    String   @default(\"DRAFT\") // DRAFT, ACTIVE, COMPLETED\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tenant     Tenant      @relation(fields: [tenantId], references: [id])\n  appraisals Appraisal[]\n}\n\nmodel Appraisal {\n  id            String    @id @default(cuid())\n  cycleId       String\n  storeId       String?\n  employeeId    String\n  managerId     String\n  status        String    @default(\"PENDING\") // PENDING, SELF_REVIEW, MANAGER_REVIEW, COMPLETED\n  selfRating    Int?\n  managerRating Int?\n  overallRating Int?\n  strengths     String?\n  improvements  String?\n  goals         String?\n  meetingNotes  String?\n  completedAt   DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  cycle    AppraisalCycle @relation(fields: [cycleId], references: [id])\n  store    Store?         @relation(fields: [storeId], references: [id])\n  employee User           @relation(\"AppraisalEmployee\", fields: [employeeId], references: [id])\n  manager  User           @relation(\"AppraisalManager\", fields: [managerId], references: [id])\n}\n\n// ============================================================\n// Shift Planning / Scheduling\n// ============================================================\n\nmodel ShiftTemplate {\n  id        String   @id @default(cuid())\n  storeId   String\n  name      String\n  dayOfWeek Int // 0=Sun, 1=Mon ... 6=Sat\n  startTime String // \"09:00\"\n  endTime   String // \"17:00\"\n  minStaff  Int      @default(1)\n  role      String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store Store @relation(fields: [storeId], references: [id])\n}\n\nmodel ShiftEntry {\n  id        String   @id @default(cuid())\n  storeId   String\n  userId    String\n  date      DateTime\n  startTime String\n  endTime   String\n  role      String?\n  status    String   @default(\"PLANNED\") // PLANNED, CONFIRMED, SWAPPED, CANCELLED\n  createdBy String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store Store              @relation(fields: [storeId], references: [id])\n  user  User               @relation(fields: [userId], references: [id])\n  swaps ShiftSwapRequest[]\n}\n\nmodel ShiftSwapRequest {\n  id             String   @id @default(cuid())\n  shiftEntryId   String\n  requestedBy    String\n  swapWithUserId String?\n  status         String   @default(\"PENDING\") // PENDING, APPROVED, REJECTED\n  approvedBy     String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  shiftEntry ShiftEntry @relation(fields: [shiftEntryId], references: [id])\n  requester  User       @relation(\"SwapRequester\", fields: [requestedBy], references: [id])\n}\n\n// ============================================================\n// Pulse Surveys\n// ============================================================\n\nmodel PulseSurvey {\n  id          String    @id @default(cuid())\n  tenantId    String\n  title       String\n  status      String    @default(\"DRAFT\") // DRAFT, ACTIVE, CLOSED\n  startDate   DateTime?\n  endDate     DateTime?\n  isAnonymous Boolean   @default(true)\n  createdBy   String?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  tenant    Tenant          @relation(fields: [tenantId], references: [id])\n  questions PulseQuestion[]\n  responses PulseResponse[]\n}\n\nmodel PulseQuestion {\n  id        String  @id @default(cuid())\n  surveyId  String\n  text      String\n  type      String  @default(\"RATING\") // RATING, TEXT, CHOICE\n  options   String? // JSON string for choices\n  sortOrder Int     @default(0)\n\n  survey  PulseSurvey   @relation(fields: [surveyId], references: [id])\n  answers PulseAnswer[]\n}\n\nmodel PulseResponse {\n  id           String   @id @default(cuid())\n  surveyId     String\n  storeId      String?\n  respondentId String?\n  submittedAt  DateTime @default(now())\n\n  survey  PulseSurvey   @relation(fields: [surveyId], references: [id])\n  store   Store?        @relation(fields: [storeId], references: [id])\n  answers PulseAnswer[]\n}\n\nmodel PulseAnswer {\n  id          String  @id @default(cuid())\n  responseId  String\n  questionId  String\n  valueRating Int?\n  valueText   String?\n  valueChoice String?\n\n  response PulseResponse @relation(fields: [responseId], references: [id])\n  question PulseQuestion @relation(fields: [questionId], references: [id])\n}\n\n// ============================================================\n// Wellbeing\n// ============================================================\n\nmodel WellbeingCheckIn {\n  id             String   @id @default(cuid())\n  tenantId       String\n  storeId        String?\n  userId         String?\n  date           DateTime @default(now())\n  moodScore      Int // 1-5\n  energyLevel    Int // 1-5\n  stressLevel    Int // 1-5\n  workloadRating Int // 1-5\n  notes          String?\n  isAnonymous    Boolean  @default(false)\n  createdAt      DateTime @default(now())\n\n  tenant Tenant @relation(fields: [tenantId], references: [id])\n  store  Store? @relation(fields: [storeId], references: [id])\n  user   User?  @relation(fields: [userId], references: [id])\n}\n\nmodel WellbeingResource {\n  id          String   @id @default(cuid())\n  tenantId    String\n  title       String\n  category    String?\n  description String?\n  url         String?\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  tenant Tenant @relation(fields: [tenantId], references: [id])\n}\n"
}

